{
  "assets": [
    {
      "asset": "product",
      "join_key": null
    }
  ],
  "blocking_issues": [],
  "dimensions": [],
  "filters": [
    "on_sale = true（在售状态，写在指标 expression 内）"
  ],
  "grain": "product（SKU 粒度存量快照，无分组，单行汇总）",
  "limit": 1,
  "metrics": [
    {
      "caliber": "COUNT(*) WHERE on_sale = true；存量计数（维表快照），过滤条件 on_sale = true 写在 expression 里，不写 on_sale <> false（避免漏掉 on_sale IS NULL 的行）",
      "name": "on_sale_product_cnt"
    }
  ],
  "order_by": [],
  "output_columns": [
    "on_sale_product_cnt"
  ],
  "time_range": {
    "end": null,
    "start": null
  }
}

